import { forbidden, unauthorized } from 'next/navigation'
import { verifyAdmin } from '@/app/lib/auth'

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin()

  // No session at all -> 401, renders app/unauthorized.tsx
  if (!session) {
    unauthorized()
  }

  // Signed in but missing the admin role -> 403, renders app/forbidden.tsx.
  // This must run before any Suspense boundary / loading.tsx starts streaming,
  // otherwise the response status is already locked in as 200.
  if (!isAdmin) {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session.name}!</p>
    </main>
  )
}

